func processPayment(amountString: String?, defaultCurrency: String?) -> String {
    // 1. guard let: Early exit, amount được dùng tiếp ở toàn bộ scope bên dưới
    guard let amount = amountString, !amount.isEmpty else {
        return "Error: Missing amount"
    }

    // 2. nil-coalescing: Cung cấp fallback giá trị mặc định
    let currency = defaultCurrency ?? "USD"

    // 3. if let: Scope hẹp cho logic điều kiện cục bộ
    if let numericAmount = Double(amount), numericAmount > 1000 {
        return "Large Transaction: \(numericAmount) \(currency) requires OTP"
    }

    return "Transaction: \(amount) \(currency)"
}

