final class DataFetcher {
    var onDataLoaded: (() -> Void)?

    // 1. Escaping closure: Lưu trữ closure vượt khỏi hàm
    func registerCallback(completion: @escaping () -> Void) {
        self.onDataLoaded = completion
    }
}

final class ProfileViewModel {
    private let fetcher = DataFetcher()
    var username: String = "Alice"

    func setupBindings() {
        // Bắt buộc dùng [weak self] để tránh retain cycle:
        // self giữ fetcher -> fetcher giữ onDataLoaded -> onDataLoaded giữ strong self
        fetcher.registerCallback { [weak self] in
            guard let self else { return }
            print("Loaded data for: \(self.username)")
        }
    }

    deinit { print("ProfileViewModel deallocated") }
}

