import UIKit

final class CustomHeaderView: UIView {
    let titleLabel = UILabel()
    let badgeImageView = UIImageView()

    override init(frame: CGRect) {
        super.init(frame: frame)
        setupLayout()
    }
    required init?(coder: NSCoder) { fatalError() }

    private func setupLayout() {
        // Bắt buộc tắt AutoresizingMask để kích hoạt AutoLayout bằng code
        titleLabel.translatesAutoresizingMaskIntoConstraints = false
        badgeImageView.translatesAutoresizingMaskIntoConstraints = false

        addSubview(titleLabel)
        addSubview(badgeImageView)

        // Sử dụng NSLayoutAnchor hiện đại, type-safe (thay thế cho VFL cũ)
        NSLayoutConstraint.activate([
            badgeImageView.leadingAnchor.constraint(equalTo: leadingAnchor, constant: 16),
            badgeImageView.centerYAnchor.constraint(equalTo: centerYAnchor),
            badgeImageView.widthAnchor.constraint(equalToConstant: 24),
            badgeImageView.heightAnchor.constraint(equalToConstant: 24),

            titleLabel.leadingAnchor.constraint(equalTo: badgeImageView.trailingAnchor, constant: 12),
            titleLabel.trailingAnchor.constraint(equalTo: trailingAnchor, constant: -16),
            titleLabel.centerYAnchor.constraint(equalTo: centerYAnchor)
        ])
    }
}

