// 2. Tiếp cận hiện đại: Tuyến tính, an toàn, dễ đọc với async/await
actor UserService {
    func fetchUserPermissions(userID: String) async throws -> AuthProfile {
        let authURL = URL(string: "https://api.example.com/auth")!
        let (authData, _) = try await URLSession.shared.data(from: authURL)
        let token = String(decoding: authData, as: UTF8.self)

        var request = URLRequest(url: URL(string: "https://api.example.com/profile/\(userID)")!)
        request.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization")

        let (profileData, _) = try await URLSession.shared.data(for: request)
        let permissions = try JSONDecoder().decode([String].self, from: profileData)

        return AuthProfile(token: token, permissions: permissions)
    }
}

import Foundation

struct AccountBalance: Sendable {
    let accountId: String
    let balance: Decimal
}

func fetchAllBalances(accountIds: [String]) async throws -> [AccountBalance] {
    // Sử dụng withThrowingTaskGroup cho structured concurrency song song
    try await withThrowingTaskGroup(of: AccountBalance.self) { group in
        for id in accountIds {
            // Mỗi child task chạy đồng thời trên Cooperative Thread Pool
            group.addTask {
                // Kiểm tra cancellation trước khi thực hiện
                try Task.checkCancellation()
                let url = URL(string: "https://api.bank.com/balance/\(id)")!
                let (data, _) = try await URLSession.shared.data(from: url)
                let balance = try JSONDecoder().decode(Decimal.self, from: data)
                return AccountBalance(accountId: id, balance: balance)
            }
        }

        var results: [AccountBalance] = []
        for try await balance in group {
            results.append(balance)
        }
        return results
    }
}

// Khai báo Actor để quản lý bộ nhớ đệm an toàn tuyệt đối khỏi Data Race
actor ImageMemoryCache {
    private var cache: [String: Data] = [:]

    func store(data: Data, for key: String) {
        // Truy cập nội bộ được đảm bảo độc quyền, không cần lock
        cache[key] = data
    }

    func retrieve(for key: String) -> Data? {
        return cache[key]
    }
}

// Sử dụng từ các luồng bất đồng bộ:
func testActorConcurrency(cache: ImageMemoryCache) async {
    // Bắt buộc dùng 'await' khi gọi từ bên ngoài actor boundary
    await cache.store(data: Data([0x01]), for: "avatar_user_1")
    let cachedData = await cache.retrieve(for: "avatar_user_1")
    print("Retrieved data size: \(cachedData?.count ?? 0)")
}

