// Đánh dấu @MainActor đảm bảo toàn bộ class được cô lập trên Main Thread
@MainActor
final class NotificationBannerViewModel: ObservableObject {
    @Published var alertMessage: String = ""
    @Published var isVisible: Bool = false

    // Tác vụ async tự động dispatch về Main Thread khi cập nhật state
    func showBanner(message: String) async {
        // Gọi tác vụ background an toàn
        let formatted = await formatMessageInBackground(message)

        // Gán trực tiếp cho @Published mà không cần DispatchQueue.main.async
        self.alertMessage = formatted
        self.isVisible = true
    }

    // Đưa việc xử lý nặng ra khỏi MainActor bằng nonisolated
    nonisolated private func formatMessageInBackground(_ raw: String) async -> String {
        // Chạy trên Cooperative Background Pool
        return raw.trimmingCharacters(in: .whitespacesAndNewlines).uppercased()
    }
}

import Foundation

final class ImageDownloaderService {
    // Tạo private serial queue để bảo vệ truy cập mảng lịch sử
    private let syncQueue = DispatchQueue(label: "com.app.imagesync.serial")
    private var downloadHistory: [String] = []

    func recordDownload(filename: String) {
        // Serial queue đảm bảo thao tác ghi không bao giờ bị race condition
        syncQueue.sync {
            downloadHistory.append(filename)
        }
    }

    func processLargeImage(data: Data) {
        // Chạy trên Concurrent Global Queue với mức ưu tiên Utility (tiết kiệm pin)
        DispatchQueue.global(qos: .utility).async {
            let processedData = data // Giả lập giải nén hình ảnh nặng

            // Dispatch ngược về Main Queue để cập nhật UI
            DispatchQueue.main.async {
                print("Rendered image on main thread, size: \(processedData.count)")
            }
        }
    }
}

import Foundation

func loadInitialAppData(completion: @escaping () -> Void) {
    let group = DispatchGroup()

    // Tác vụ 1: Fetch Remote Config
    group.enter()
    DispatchQueue.global().asyncAfter(deadline: .now() + 0.5) {
        print("Config loaded")
        group.leave()
    }

    // Tác vụ 2: Fetch User Permissions
    group.enter()
    DispatchQueue.global().asyncAfter(deadline: .now() + 0.8) {
        print("Permissions loaded")
        group.leave()
    }

    // Khi tất cả tác vụ trong group đã gọi leave(), notify trên Main Thread
    group.notify(queue: .main) {
        print("Tất cả tác vụ hoàn tất, chuyển vào HomeScreen")
        completion()
    }
}

// Sử dụng DispatchWorkItem để hủy tác vụ tìm kiếm (Debounce)
var searchWorkItem: DispatchWorkItem?
func onSearchQueryChanged(query: String) {
    searchWorkItem?.cancel() // Hủy tác vụ cũ chưa kịp chạy

    let workItem = DispatchWorkItem { print("Executing search for: \(query)") }
    searchWorkItem = workItem
    DispatchQueue.main.asyncAfter(deadline: .now() + 0.3, execute: workItem)
}

