import Foundation
import Combine

final class SearchViewModel {
    // Input Subject nhận sự kiện gõ phím từ UI
    let searchQuerySubject = PassthroughSubject<String, Never>()

    // Output Publisher cho View lắng nghe kết quả
    private(set) var searchResults: [String] = []
    private var cancellables = Set<AnyCancellable>()

    init() {
        searchQuerySubject
            .debounce(for: .milliseconds(300), scheduler: DispatchQueue.main)
            .removeDuplicates()
            .filter { $0.count >= 2 }
            // Dùng map + switchToLatest để hủy bỏ request cũ khi người dùng gõ tiếp
            .map { [weak self] query -> AnyPublisher<[String], Never> in
                guard let self = self else { return Empty().eraseToAnyPublisher() }
                return self.fetchSearchResultsPublisher(for: query)
            }
            .switchToLatest()
            .share() // Chia sẻ luồng cho nhiều subscriber mà không lặp lại network call
            .receive(on: DispatchQueue.main)
            .sink { [weak self] results in
                self?.searchResults = results
                print("Updated results count: \(results.count)")
            }
            .store(in: &cancellables)
    }

    private func fetchSearchResultsPublisher(for query: String) -> AnyPublisher<[String], Never> {
        // Giả lập API call trả về Publisher
        Just(["\(query) - Pro", "\(query) - Max"])
            .eraseToAnyPublisher()
    }
}

