import BackgroundTasks
import UIKit

final class BackgroundSyncManager {
    static let shared = BackgroundSyncManager()
    let refreshTaskId = "com.nextpro.app.refresh"
    let processingTaskId = "com.nextpro.app.dbcleanup"

    func registerBackgroundTasks() {
        // Bắt buộc đăng ký trước khi kết thúc launch sequence
        BGTaskScheduler.shared.register(forTaskWithIdentifier: refreshTaskId, using: nil) { task in
            guard let refreshTask = task as? BGAppRefreshTask else { return }
            self.handleAppRefresh(task: refreshTask)
        }
    }

    private func handleAppRefresh(task: BGAppRefreshTask) {
        // 1. Lập lịch cho lần chạy kế tiếp ngay lập tức
        scheduleNextAppRefresh()

        let queue = OperationQueue()
        queue.maxConcurrentOperationCount = 1

        // 2. Thiết lập expirationHandler để tránh bị hệ thống crash Watchdog
        task.expirationHandler = {
            queue.cancelAllOperations()
            print("Background task hết hạn thời gian, dọn dẹp ngay!")
        }

        // 3. Thực thi công việc đồng bộ nhẹ
        let operation = BlockOperation {
            // Giả lập đồng bộ dữ liệu
            Thread.sleep(forTimeInterval: 2.0)
            print("Hoàn tất đồng bộ ngầm")
        }

        operation.completionBlock = {
            task.setTaskCompleted(success: !operation.isCancelled)
        }
        queue.addOperation(operation)
    }

    func scheduleNextAppRefresh() {
        let request = BGAppRefreshTaskRequest(identifier: refreshTaskId)
        request.earliestBeginDate = Date(timeIntervalSinceNow: 15 * 60) // Tối thiểu sau 15 phút
        try? BGTaskScheduler.shared.submit(request)
    }
}

import Foundation
import CoreData

struct TaskDTO: Codable {
    let id: UUID
    let title: String
    let updatedAt: Date
    let isDeleted: Bool
}

final class SyncConflictResolver {
    // Chiến lược Last-Write-Wins (LWW) giải quyết xung đột giữa Local và Remote
    func resolveConflict(
        localEntity: NSManagedObject,
        remoteDTO: TaskDTO
    ) -> (shouldUpdateLocal: Bool, reason: String) {
        let localUpdatedAt = (localEntity.value(forKey: "updatedAt") as? Date) ?? Date.distantPast

        if remoteDTO.updatedAt > localUpdatedAt {
            // Dữ liệu trên Server mới hơn -> Ghi đè vào Local
            localEntity.setValue(remoteDTO.title, forKey: "title")
            localEntity.setValue(remoteDTO.updatedAt, forKey: "updatedAt")
            localEntity.setValue(remoteDTO.isDeleted, forKey: "isDeleted")
            localEntity.setValue(false, forKey: "isSyncPending")
            return (true, "Server wins: Server timestamp newer")
        } else {
            // Dữ liệu Local mới hơn -> Giữ nguyên local và đánh dấu đẩy ngược lên Server
            localEntity.setValue(true, forKey: "isSyncPending")
            return (false, "Local wins: Client modification newer, queueing upload")
        }
    }
}

