import Foundation

final class GameLevelAssetManager {
    private var resourceRequest: NSBundleResourceRequest?

    // Tải tài nguyên theo nhu cầu (On-Demand Resources) cho Level 2
    func loadLevelAssets(tag: String) async throws {
        // 1. Khởi tạo request với tag đã gắn trong Asset Catalog
        let tags = Set([tag])
        let request = NSBundleResourceRequest(tags: tags)
        self.resourceRequest = request

        // 2. Kiểm tra xem tài nguyên đã có sẵn trong máy chưa
        let isAvailable = await request.conditionallyBeginAccessingResources()
        if isAvailable {
            print("Tài nguyên đã nằm sẵn trong bộ nhớ đệm")
            return
        }

        // 3. Nếu chưa có, tải về từ Apple App Store CDN
        try await request.beginAccessingResources()
        print("Tải hoàn tất tài nguyên cho tag: \(tag)")
    }

    func releaseAssets() {
        // 4. Giải phóng để hệ điều hành có thể purge bộ nhớ khi máy cạn dung lượng
        resourceRequest?.endAccessingResources()
        resourceRequest = nil
    }
}
